      {"q": "Com es pronuncia «mnemotècnia»?", "o": ["[nemotɛ́gnia], amb la m inicial muda", "[mnemotɛ́knia], amb m i n", "[memotɛ́knia], sense n"], "e": "S'emmudix la primera consonant dels grups cultes gm, mn i pn a principi de paraula: [n]emotècnia, gnom, pneumàtic (GNV 1.3.2.7.1.f)."},
      {"q": "Com es pronuncia «amnèsia»?", "o": ["[amnɛ́zia], pronunciant m i n", "[anɛ́zia], amb n sola", "[ammɛ́zia], amb geminada"], "e": "En interior de paraula el grup mn es pronuncia amb les dos consonants: a[mn]èsia (Quadern C2; DNV)."},
      {"q": "Quina sèrie conté només formes correctes?", "o": ["condemnar, indemnitzar, damnificat", "condenar, indennitzar, danificat", "condemnar, indennitzar, damnificat"], "e": "Són cultismes amb el grup mn: condemnar [kondemnáɾ], indemnitzar [indemnizáɾ], damnificat (DNV)."},
      {"q": "Quina sèrie és correcta?", "o": ["insomni, gimnàs, himne", "insonni, ginàs, imne", "insomni, gimnàs, imne"], "e": "Insomni [insɔ́mni], gimnàs [ʤimnás] i himne [ímne], amb el grup mn (DNV)."},
      {"q": "Escriu l'adjectiu que designa la persona que camina adormida.", "a": ["somnàmbul"], "e": "Somnàmbul [somnámbul], amb mn com somni i insomni (DNV)."},
      {"q": "Escriu el contrari de «mòbil» format amb el prefix in-.", "a": ["immòbil"], "e": "El prefix in- davant de m s'escriu im-: immòbil [immɔ́bil], amb m geminada (GNV 4.12.a; DNV)."},
      {"q": "Quina és la forma correcta?", "o": ["solemne", "solene", "solenne"], "e": "Solemne [solémne], amb el grup mn (DNV)."},
      {"q": "Quina sèrie és correcta?", "o": ["tramvia, triumvir, circumval·lació", "tranvia, triunvir, circunval·lació", "tramvia, triunvir, circumval·lació"], "e": "Davant de v s'escriu n, però es manté la m en formes prefixades, compostos i cultismes: tramvia [tɾaɱvía], triumvir, circumval·lació (GNV 4.12.b, exc.)."}
    ]
  },
  {
    "id": "15441559-2dbb-5e38-9cec-f4ccd8603baa", "type": "c2_fon_rotiques_h", "sort_order": 11,
    "title": "Ròtiques i h: regles avançades", "name": "R i rr en compostos i darrere de prefix, ròtiques difícils (sabre, crebantar), h muda i aspirada en préstecs, cultismes i topònims, kh i parelles amb h",
    "content": "Les grafies r i rr en paraules compostes (grecoromà, mata-rates, trirrem, Vila-real) i darrere de prefix (arrítmia, autoretrat, correferent, prerrogativa); ròtiques d'especial complexitat (sabre, erradicar, crebantar, ornitorrinc); la h en préstecs i cultismes, la h aspirada, altres representacions (Khartum, sikh) i parelles com ala/hala, aprendre/aprehendre, om/hom, ostatge/hostatge (3.2.1).", "icon": "🌀", "color": "#D1C4E9",
    "exercises": [
      {"q": "Com es pronuncia i s'escriu «grecoromà»?", "o": ["Amb r simple escrita, pronunciada vibrant: [gɾekoromá]", "Amb r simple, pronunciada bategant: [gɾekoɾomá]", "S'ha d'escriure «grecorromà»"], "e": "Darrere d'un formant acabat en vocal el so vibrant [r] s'escriu amb r simple: greco[r]omà (GNV 4.16.b, exc.; DNV)."},
      {"q": "Escriu l'adjectiu que significa 'de les cultures grega i romana alhora'.", "a": ["grecoromà"], "e": "Grecoromà [gɾekoromá], amb r simple que sona vibrant (GNV 4.16.b, exc.)."},
      {"q": "Quina sèrie conté només formes correctes?", "o": ["grecoromà, vicerector, contrarestar", "grecorromà, vicerrector, contrarrestar", "grecoromà, vicerrector, contrarestar"], "e": "La r vibrant s'escriu simple quan seguix un prefix, una forma prefixada o un formant acabat en vocal: vicerector [viserektóɾ], contrarestar (GNV 4.16.b, exc.)."},
      {"q": "Quina és la forma correcta?", "o": ["mata-rates", "matarrates", "matarates"], "e": "Els compostos el segon element dels quals comença per r- i el primer acaba en vocal porten guionet: mata-rates [matarátes] (GNV 5.3.d)."},
      {"q": "Quina sèrie de compostos és correcta?", "o": ["cama-roja, malva-rosa, compta-revolucions", "camarroja, malvarrosa, comptarrevolucions", "cama-roja, malvarosa, compta-revolucions"], "e": "Porten guionet perquè el segon element comença per r- i el primer acaba en vocal (GNV 5.3.d; DNV)."},
      {"q": "Escriu el gentilici masculí de Vila-real.", "a": ["vila-realenc"], "e": "Vila-realenc [vilarealéŋk]: el guionet es manté en el derivat (GNV 5.3.d)."},
      {"q": "Quina és la forma correcta del nom de la nau de guerra grega amb tres rengleres de rems?", "o": ["trirrem", "trirem", "tri-rem"], "e": "El DNV registra trirrem [tɾirém], amb rr; contrasta amb vicerector o autoretrat, amb r simple."},
      {"q": "Quina és la forma correcta?", "o": ["arrítmia", "arítmia", "a-rítmia"], "e": "Entre vocals el so [r] s'escriu rr: arrítmia [arídmia], correferent, erradicar (GNV 4.16.b)."},
      {"q": "Quina sèrie és correcta?", "o": ["arrítmia, correferent, corresponsable", "arítmia, coreferent, coresponsable", "arrítmia, coreferent, corresponsable"], "e": "S'escriuen amb rr: arrítmia, correferent [korefeɾént], corresponsable [koresponsáble] (GNV 4.16.b; DNV)."},
      {"q": "Quina és la forma correcta?", "o": ["autoretrat", "autorretrat", "auto-retrat"], "e": "Darrere de la forma prefixada auto- s'escriu r simple, pronunciada vibrant: autoretrat [awtoretɾát] (GNV 4.16.b, exc.; DNV)."},
      {"q": "Quina parella és correcta?", "o": ["prerrogativa i preromànic", "prerogativa i prerromànic", "prerrogativa i prerromànic"], "e": "El DNV registra prerrogativa [pɾeroɣatíva], amb rr, però preromànic [pɾerománik], amb r simple darrere del prefix pre-."},
      {"q": "Quina forma registra el DNV?", "o": ["bioritme", "biorritme", "bio-ritme"], "e": "Bioritme [biorídme], amb r simple darrere de la forma prefixada bio- (GNV 4.16.b, exc.; DNV)."},
      {"q": "Quina és la forma correcta?", "o": ["contrarellotge", "contrarrellotge", "contra-rellotge"], "e": "Contrarellotge [kontɾareʎɔ́ʤe], amb r simple després de contra- (DNV)."},
      {"q": "Per què s'escriu amb guionet «pit-roig»?", "o": ["Perquè l'aglutinació dificultaria la lectura dels components", "Perquè els dos elements són adjectius", "Perquè és un préstec no adaptat"], "e": "Porten guionet els compostos en què l'aglutinació pot alterar la lectura: pit-roig [pidrɔ́ʧ], cor-robat, Bell-lloc (GNV 5.3.e)."},
      {"q": "Escriu el nom de l'arma blanca semblant a l'espasa, de fulla corba (cast. «sable»).", "a": ["sabre"], "e": "Sabre [sábɾe], amb r (Quadern C2; DNV)."},
      {"q": "Quina és la forma correcta del verb que significa 'trencar' o 'fer perdre consistència'?", "o": ["crebantar", "quebrantar", "crabantar"], "e": "Crebantar [kɾebantáɾ] (cast. «quebrantar») (Quadern C2; DNV)."},
      {"q": "Quina és la forma correcta?", "o": ["erradicar", "eradicar", "erredicar"], "e": "Erradicar [eraðikáɾ], amb rr entre vocals (GNV 4.16.b; DNV)."},
      {"q": "Com s'escriu el mamífer australià amb bec d'ànec?", "o": ["ornitorrinc", "ornitorinc", "ornitorrinco"], "e": "Ornitorrinc [oɾnitoríŋk], amb rr i -c final (GNV 4.16.b; DNV)."},
      {"q": "Quina és la forma correcta?", "o": ["otorrinolaringòleg", "otorinolaringòleg", "otorrinolaringòlec"], "e": "Otorrinolaringòleg [otorinolaɾiŋgɔ́lek], amb rr i -g final pel derivat otorrinolaringologia (GNV 4.16.b; DNV)."},
      {"q": "Escriu la forma abreujada d'«otorrinolaringòleg».", "a": ["otorrino"], "e": "Otorrino [otoríno], amb rr com la forma completa (DNV)."},
      {"q": "Com es pronuncia «hàmster»?", "o": ["[hámsteɾ], amb h aspirada", "[ámsteɾ], amb h muda", "[xámsteɾ], amb fricativa velar"], "e": "En el préstec adaptat hàmster la h es pronuncia aspirada: [h]àmster (Quadern C2; DNV)."},
      {"q": "Com es pronuncia «handbol»?", "o": ["[ambɔ́l], amb h muda", "[hanbɔ́l], amb h aspirada", "[xandbɔ́l]"], "e": "En handbol la h és muda: [am]bol (Quadern C2; DNV)."},
      {"q": "Escriu el nom de l'esport d'equip que es juga amb les mans i una pilota, que té una h muda inicial.", "a": ["handbol"], "e": "Handbol [ambɔ́l]: préstec adaptat amb h muda."},
      {"q": "En quina d'estes paraules la h és muda?", "o": ["hamburguesa", "hàmster", "hobby"], "e": "El DNV dona hamburguesa [ambuɾɣéza], amb h muda; hàmster [hámsteɾ] i hobby [hɔ́bi] la pronuncien aspirada."},
      {"q": "Quina sèrie de cultismes és correcta?", "o": ["subtrahend, hidròfob, hexagonal", "sustraend, idròfob, exagonal", "subtrahend, idròfob, hexagonal"], "e": "Són cultismes amb h muda: subtrahend [suptɾaént], hidròfob [iðɾɔ́fop], hexagonal [egzaɣonál] (Quadern C2; DNV)."},
      {"q": "Quina sèrie de cultismes és correcta?", "o": ["hendecasíl·lab, hecatombe, hagiografia", "endecasíl·lab, ecatombe, agiografia", "hendecasíl·lab, ecatombe, hagiografia"], "e": "Cultismes grecs amb h inicial muda: hendecasíl·lab [endekasílap], hecatombe, hagiografia [aʤioɣɾafía] (DNV)."},
      {"q": "Escriu el nom de l'espai semicircular on es reunixen els diputats en un parlament.", "a": ["hemicicle"], "e": "Hemicicle [emisíkle], cultisme amb h muda (DNV)."},
      {"q": "En quina d'estes paraules la h es pronuncia aspirada?", "o": ["ehem!", "hala!", "harmonia"], "e": "En certes interjeccions la h es pronuncia aspirada: ehem! [ehém], ha, ha!; en hala! [ála] i harmonia és muda (GNV 4.17, obs.; DNV)."},
      {"q": "Com es pronuncia «hegelià»?", "o": ["[heɣeliá], amb h aspirada", "[eɣeliá], amb h muda", "[xeɣeliá], amb fricativa velar"], "e": "En els derivats de noms propis estrangers la h es pronuncia aspirada: Hegel, hegelià (GNV 4.17, obs.; DNV)."},
      {"q": "Quina és la forma correcta?", "o": ["el hegelianisme", "l'hegelianisme", "lo hegelianisme"], "e": "Davant de h aspirada l'article i la preposició de no s'apostrofen: el hegelianisme, de Hollywood (GVB 10.6)."},
      {"q": "Quina frase és correcta?", "o": ["Són originaris de Hawaii.", "Són originaris d'Hawaii.", "Són originaris de Hawai."], "e": "Hawaii, topònim no adaptat amb h aspirada, no admet l'apostrofació de la preposició (Quadern C2; GVB 10.6). El gentilici és hawaià [hawajá]."},
