  {
    "id": "0ee49ff8-c794-56ae-a543-90da1b518499", "type": "c2_fon_convencions", "sort_order": 12,
    "title": "Majúscules, tipus de lletra i abreviacions", "name": "Majúscules (càrrecs, tractaments, protocol, institucions, topònims, vies urbanes), redona, cursiva, negreta i versaleta, abreviacions i xifres",
    "content": "Funció demarcativa i distintiva de les majúscules en càrrecs oficials, formes de tractament i protocol·làries, institucions i entitats, topònims amb article i noms de places i carrers; usos de la redona, la cursiva, la negreta i la versaleta; abreviatures, símbols, sigles i acrònims; xifres i quantitats, amb criteris de mesura, coherència i pertinència (3.2.1).", "icon": "🔠", "color": "#C5CAE9",
    "exercises": [
      {"q": "En «Ja ve la Fira de Juliol», quina funció té cada majúscula?", "o": ["«Ja», demarcativa; «Fira» i «Juliol», distintiva", "Totes, distintives", "Totes, demarcatives"], "e": "La majúscula demarcativa marca la posició (inici de frase); la distintiva identifica un nom propi, com el d'una festivitat (GNV 6.1.1 i 6.1.3.f)."},
      {"q": "Quina frase està ben escrita?", "o": ["La presidenta de les Corts ha inaugurat l'exposició.", "La Presidenta de les Corts ha inaugurat l'exposició.", "La presidenta de les corts ha inaugurat l'exposició."], "e": "La designació estricta dels càrrecs va en minúscula; el nom de la institució, en majúscula (GNV 6.1.3.k, obs.; GVB 12.10)."},
      {"q": "Quina forma és correcta en l'encapçalament d'un discurs oficial?", "o": ["el Molt Honorable Senyor President de la Generalitat", "el molt honorable senyor president de la Generalitat", "el Molt Honorable senyor president de la generalitat"], "e": "Les formes protocol·làries de tractament s'escriuen amb majúscula inicial (GNV 6.1.3.k; GVB 12.12)."},
      {"q": "Quina forma és correcta?", "o": ["mossén Alcover, però Mn. Alcover", "Mossén Alcover i Mn. Alcover", "mossén Alcover i mn. Alcover"], "e": "Les formes de tractament que precedixen un nom propi van en minúscula, però les seues abreviatures sempre porten majúscula inicial: la senyora Gomis, la Sra. Gomis (GVB 12.11)."},
      {"q": "Quina frase està ben escrita?", "o": ["Treballa en l'església de Santa Caterina, prop de la imatge de santa Rosa.", "Treballa en l'església de santa Caterina, prop de la imatge de Santa Rosa.", "Treballa en l'Església de Santa Caterina, prop de la imatge de Santa Rosa."], "e": "Sant/santa és un tractament (minúscula), però va amb majúscula quan s'integra en el nom d'una església, un topònim o una festa (GVB 12.11). L'edifici es diu església, en minúscula (GVB 12.19)."},
      {"q": "Quina adreça està ben escrita?", "o": ["la plaça del Pintor Jacomart", "la Plaça del pintor Jacomart", "la plaça del pintor Jacomart"], "e": "El genèric de la via va en minúscula; els tractaments, càrrecs i professions integrats en la toponímia urbana, en majúscula (GVB 12.11 i 12.25)."},
      {"q": "Quina sèrie de topònims està ben escrita?", "o": ["l'Eliana, el Puig, la Font d'en Carròs", "L'Eliana, El Puig, La Font d'En Carròs", "l'Eliana, el Puig, la Font d'En Carròs"], "e": "Els articles, preposicions i conjuncions dels topònims valencians o valencianitzats van en minúscula (GNV 6.1.3.j, obs.)."},
      {"q": "Quina frase està ben escrita en un text en valencià?", "o": ["Viatjarem a Le Havre i a Los Angeles.", "Viatjarem a le Havre i a los Angeles.", "Viatjarem a Le Havre i a los Angeles."], "e": "Els articles dels topònims no valencians ni valencianitzats porten majúscula inicial: Le Havre, Los Angeles, La Spezia (GNV 6.1.3.j, obs.)."},
      {"q": "Quina sèrie està ben escrita?", "o": ["el mar Mediterrani, la serra de Mariola, la Font Roja", "el Mar Mediterrani, la Serra de Mariola, la font Roja", "el mar Mediterrani, la Serra de Mariola, la Font roja"], "e": "Mar i serra són genèrics (minúscula); en la Font Roja el genèric forma part del topònim (GNV 6.1.3.j, obs.)."},
      {"q": "Quina frase està ben escrita?", "o": ["Les conselleries implicades es reuniran amb l'Ajuntament de Gandia.", "Les Conselleries implicades es reuniran amb l'ajuntament de Gandia.", "Les conselleries implicades es reuniran amb l'ajuntament de Gandia."], "e": "Els noms d'institucions concretes van amb majúscula; en plural o amb sentit genèric, en minúscula (GNV 6.1.3.e; GVB 12.16)."},
      {"q": "«Treballa en la ___» (referint-se a la Conselleria d'Educació, ja esmentada)", "o": ["Conselleria", "conselleria", "CONSELLERIA"], "e": "Les mencions abreujades d'una institució concreta també porten majúscula inicial: la Conselleria, la Universitat, l'Acadèmia (GVB 12.16)."},
      {"q": "Quina frase està ben escrita?", "o": ["El consistori i la cambra alta han aprovat la proposta.", "El Consistori i la Cambra Alta han aprovat la proposta.", "El consistori i la Cambra alta han aprovat la proposta."], "e": "Les denominacions correferents (el consistori per l'Ajuntament, la cambra alta pel Senat) s'escriuen en minúscula (GVB 12.17)."},
      {"q": "Quina forma és correcta?", "o": ["l'Administració pública", "l'Administració Pública", "l'administració Pública"], "e": "En les institucions juridicopúbliques, militars i religioses va en majúscula el substantiu, però no l'adjectiu: l'Estat espanyol, l'Església catòlica (GVB 12.19)."},
      {"q": "Quina sèrie està ben escrita?", "o": ["el Codi Civil i la Llei d'accessibilitat universal de la Comunitat Valenciana", "el Codi civil i la Llei d'Accessibilitat Universal de la Comunitat Valenciana", "el codi civil i la llei d'accessibilitat universal de la Comunitat Valenciana"], "e": "Els compendis normatius singulars porten majúscula en substantius i adjectius; les disposicions legals de caràcter regular, només en la primera paraula (GNV 6.1.3.n i obs.)."},
      {"q": "Quina frase està ben escrita?", "o": ["Ho establix l'article 21 del títol III de la Constitució Espanyola.", "Ho establix l'Article 21 del Títol III de la Constitució Espanyola.", "Ho establix l'article 21 del títol III de la constitució espanyola."], "e": "Les parts genèriques de les disposicions legals (article, títol, apartat, preàmbul) van en minúscula (GVB 12.32)."},
      {"q": "Com s'escriu el títol d'esta novel·la?", "o": ["El mut de la campana", "El Mut de la Campana", "el mut de la campana"], "e": "En els títols de llibres, pel·lícules o obres teatrals només porta majúscula la primera paraula (GVB 12.30)."},
      {"q": "Com s'escriu el títol d'esta publicació periòdica?", "o": ["Revista d'Estudis Fallers", "Revista d'estudis fallers", "revista d'Estudis Fallers"], "e": "En el títol de les publicacions periòdiques porten majúscula la primera paraula i tots els substantius i adjectius (GVB 12.30)."},
      {"q": "Quina frase està ben escrita?", "o": ["És llicenciada en Història Contemporània, però li agraden els llibres d'història antiga.", "És llicenciada en història contemporània, però li agraden els llibres d'Història Antiga.", "És llicenciada en Història contemporània, però li agraden els llibres d'Història antiga."], "e": "Les titulacions i assignatures oficials porten majúscula; les disciplines en sentit genèric, minúscula (GNV 6.1.3.l; GVB 12.29)."},
      {"q": "Quina frase està ben escrita?", "o": ["La Il·lustració va coincidir amb l'auge del neoclassicisme.", "La il·lustració va coincidir amb l'auge del Neoclassicisme.", "La Il·lustració va coincidir amb l'auge del Neoclassicisme."], "e": "Els períodes històrics singulars van amb majúscula (el Renaixement, la Il·lustració); els moviments artístics i culturals, en minúscula (el barroc, el cubisme) (GVB 12.23 i 12.24)."},
      {"q": "Quina sèrie està ben escrita?", "o": ["el dijous, el desembre, la tardor, el Nou d'Octubre", "el Dijous, el Desembre, la Tardor, el nou d'octubre", "el dijous, el desembre, la tardor, el nou d'Octubre"], "e": "Les divisions temporals cícliques van en minúscula; les festivitats, en majúscula (GVB 12.20 i 12.22; GNV 6.1.3.f)."},
      {"q": "Quina frase està ben escrita?", "o": ["Conduïx un Renault, beu vi de Requena-Utiel i pren un xerés.", "Conduïx un renault, beu vi de requena-utiel i pren un Xerés.", "Conduïx un Renault, beu Vi de Requena-Utiel i pren un Xerés."], "e": "Les marques i denominacions d'origen porten majúscula; els noms genèrics procedents de noms propis (un xerés, un jeep) van en minúscula (GNV 6.1.3.d i obs.; GVB 12.26)."},
      {"q": "Quina sèrie està ben escrita?", "o": ["la consellera De Miguel, Isabel de Villena", "la consellera de Miguel, Isabel De Villena", "la Consellera De Miguel, Isabel de Villena"], "e": "Les partícules dels cognoms van en minúscula darrere del nom de pila, però en majúscula si encapçalen el nom propi; el càrrec, en minúscula (GVB 12.9 i 12.10)."},
      {"q": "Quina frase està ben escrita?", "o": ["Ell és, com t'ho diria?, absolutament imprevisible.", "Ell és, com t'ho diria?, Absolutament imprevisible.", "Ell és, Com t'ho diria?, absolutament imprevisible."], "e": "Si el signe d'interrogació no tanca la frase i va seguit de coma, la paraula següent va en minúscula (GNV 6.1.2.c, obs.)."},
      {"q": "Quina frase està ben escrita?", "o": ["Es va agenollar en terra. (Pensava que eixir d'aquell destret seria difícil.)", "Es va agenollar en terra. (pensava que eixir d'aquell destret seria difícil.)", "Es va agenollar en terra (Pensava que eixir d'aquell destret seria difícil.)"], "e": "Després de punt, el text del parèntesi comença amb majúscula i el punt final va dins; si no hi ha cap signe davant del parèntesi, comença amb minúscula (GVB 12.8)."},
      {"q": "Quina sèrie de topònims està ben escrita?", "o": ["Sud-àfrica, Vila-real, Guinea-Bissau", "Sud-Àfrica, Vila-Real, Guinea-Bissau", "Sud-àfrica, Vila-real, Guinea-bissau"], "e": "En els compostos aglutinats només porta majúscula el primer constituent, excepte en certs topònims estrangers no adaptats: Guinea-Bissau, Baden-Baden (GNV 6.1.1.c i obs.)."},
      {"q": "En un text en redona, com s'escriu el nom propi d'un vaixell, com el «Calypso»?", "o": ["En cursiva", "En redona", "En versaleta"], "e": "Els noms propis de naus, aeronaus, satèl·lits i trens s'escriuen en cursiva (GNV 6.2.2.d)."},
      {"q": "En «Josep Martínez Ruiz, Azorín, va nàixer a Monòver», com s'escriu «Azorín»?", "o": ["En cursiva, perquè el pseudònim acompanya el nom propi", "En redona, perquè és un nom propi", "En versaleta, perquè és un cognom"], "e": "Els pseudònims i sobrenoms van en cursiva quan acompanyen el nom propi; si s'esmenten sols, en redona (GNV 6.2.2.f i obs.)."},
      {"q": "Com s'escriu «fúting» en «Fa fúting tots els matins»?", "o": ["En redona, perquè és un estrangerisme adaptat", "En cursiva, perquè és un estrangerisme", "Entre cometes simples"], "e": "Els estrangerismes no adaptats van en cursiva; quan s'adapten gràficament, en redona (GNV 6.2.2.h i obs.; GVB 13.2.1)."},
      {"q": "Com s'escriuen els títols dels llibres sagrats, com la Bíblia o l'Alcorà?", "o": ["En redona", "En cursiva", "Entre cometes"], "e": "Els títols dels llibres sagrats i de les seues parts s'escriuen en redona (GVB 13.2.4)."},
      {"q": "En «una església del segle xiv», com es recomana escriure la xifra romana?", "o": ["En versaleta, perquè acompanya una paraula en minúscula", "En majúscules", "En cursiva"], "e": "Les xifres romanes que acompanyen una paraula en minúscula (segle, volum, tom) van en versaleta; amb una paraula amb majúscula, en majúscules: Pius V (GNV 6.2.3.a i obs.)."},
      {"q": "Escriu el nom del tipus de lletra que s'usa per als ètims, com el llatí cathedra.", "a": ["versaleta", "la versaleta"], "e": "Els ètims de les paraules se solen escriure en versaleta (GNV 6.2.3.b)."},
      {"q": "En una bibliografia, com s'escriu el cognom de l'autor («Casp, Xavier: Aires de cançó...»)?", "o": ["En versaleta, amb majúscula inicial", "En cursiva", "En negreta i majúscules"], "e": "En notes, bibliografies i índexs onomàstics els cognoms dels autors s'escriuen en versaleta (GNV 6.2.3.c)."},
      {"q": "Per a què s'usa principalment la negreta?", "o": ["Per a destacar títols d'apartats i lemes de diccionari", "Per a les paraules estrangeres no adaptades", "Per als títols de llibres i revistes"], "e": "La negreta servix per a destacar i localitzar paraules, sobretot en títols de capítols i apartats i en les entrades de diccionaris (GNV 6.2.4)."},
      {"q": "Quina forma és correcta si l'abreviatura coincidix amb punts suspensius?", "o": ["Va passar l'any 138 a. C...", "Va passar l'any 138 a. C....", "Va passar l'any 138 a.C. ..."], "e": "El punt de l'abreviatura s'omet quan coincidix amb el punt final o amb els punts suspensius (GVB 14.2.6)."},
      {"q": "Escriu l'abreviatura de «sense número», que porta una barra al mig.", "a": ["s/n"], "e": "Algunes abreviatures compostes porten una barra com a separació: s/n, c/c (GVB 14.2.2)."},
      {"q": "Escriu l'abreviatura de «compte corrent».", "a": ["c/c"], "e": "Algunes abreviatures compostes porten una barra al mig: c/c (compte corrent), r/n (referència nostra) (GNV 6.3.1.a, obs.)."},
      {"q": "Escriu l'abreviatura de l'expressió llatina «sub voce».", "a": ["s. v."], "e": "S. v., amb espai entre els elements i en cursiva, com totes les abreviatures d'expressions estrangeres (GNV 6.3.1.e)."},
      {"q": "Escriu l'abreviatura del plural de l'ordinal «quarts» amb la xifra 4.", "a": ["4ts", "4ts.", "4.ts"], "e": "Els ordinals en plural s'abreugen amb les dos últimes lletres: 4ts (quarts), 9es (novenes) (GNV 6.3.1.f, obs.)."},
      {"q": "Quin plural de l'abreviatura «f.» (foli) és correcte?", "o": ["ff. o fs.", "f.f.", "fs"], "e": "Les abreviatures d'una sola lletra fan el plural duplicant la lletra o afegint s: ff. o fs. (GNV 6.3.1.c, obs.)."},
      {"q": "Escriu el símbol d'«atmosferes».", "a": ["atm"], "e": "Atm, sense punt i invariable en plural (GNV 6.3.2.a)."},
      {"q": "Per què es diu «la IBM»?", "o": ["Perquè el gènere el determina el nom genèric subjacent, l'empresa", "Perquè totes les sigles són femenines", "Perquè la primera paraula de la sigla és femenina"], "e": "Les sigles prenen el gènere de la primera paraula de l'expressió, però a vegades el determina un nom genèric subjacent: la IBM (GNV 6.3.3.b, obs.)."},
      {"q": "Escriu com es llig la sigla PC en plural: «els ___».", "a": ["pecés"], "e": "Les sigles de conceptes en plural es lligen amb la marca de plural: els PC, els pecés; les ONG, les oenegés (GVB 14.4.5)."},
      {"q": "Quina sigla s'ha lexicalitzat i s'escriu normalment en minúscula?", "o": ["sida", "ONU", "IVAM"], "e": "Algunes sigles s'han lexicalitzat i s'escriuen en minúscula: sida, ovni, làser, elepé (GVB 14.4.2)."},
      {"q": "Escriu la sigla que s'usa en valencià per a «àcid desoxiribonucleic».", "a": ["ADN"], "e": "Les sigles no es traduïxen com a norma general, però les d'alguns conceptes i organismes internacionals sí: ADN (que alterna amb DNA), OTAN, FMI (GNV 6.3.3.e)."},
      {"q": "Quina frase seguix la tradició tipogràfica que recull la GNV?", "o": ["Només caben nou taules en l'aula 205.", "Només caben 9 taules en l'aula dos-cents cinc.", "Només caben nou taules en l'aula dos-cents cinc."], "e": "Dins del text els cardinals se solen escriure amb lletra del zero al nou i amb xifres a partir del 10 (GNV 18.3.2.f)."},
      {"q": "Quina forma és correcta?", "o": ["l'11 de gener", "el 11 de gener", "l'onze de Gener"], "e": "Els cardinals seguixen les normes d'apostrofació tant amb lletra com amb xifra: l'11 o l'onze de gener; els mesos van en minúscula (GNV 18.3.2.e)."},
      {"q": "Escriu amb lletres com es llig el número de «Joan XXIII»: «Joan ___».", "a": ["vint-i-tres"], "e": "Posposats a un nom propi, els numerals superiors a deu es lligen com a cardinals: Joan XXIII (vint-i-tres), però Joan III (tercer) (GNV 18.4.2.d)."},
      {"q": "En la primera aparició d'una sigla poc coneguda en un text, què és més adequat?", "o": ["Acompanyar-la de la denominació completa, per exemple entre parèntesis", "Escriure només la sigla", "Escriure la sigla amb punts entre les lletres"], "e": "La pertinència i la comprensió del text aconsellen explicar les sigles poc conegudes: La LOGSE (Llei d'ordenació general del sistema educatiu)... (GNV 7.5.2.a). Les sigles no porten punts (GNV 6.3.3.a)."}
    ]
  },
  {
    "id": "846ab3ae-e3a4-5570-ad0a-8e1520ab066a", "type": "c2_fon_puntuacio", "sort_order": 13,
    "title": "Signes de puntuació: regles avançades", "name": "Puntuació de les oracions compostes, comes explicatives i especificatives, punt i coma, incisos i la seua gradació, i comes que no s'han d'escriure",
    "content": "Regles avançades de puntuació: oracions compostes; ús o absència de la coma en elements explicatius o especificatius; punt i coma; signes per a introduir incisos i la seua gradació, i omissió de la coma entre el subjecte i el predicat i entre el verb i els complements directe, indirecte, atribut o predicatiu (3.2.1).", "icon": "✒️", "color": "#B3E5FC",
    "exercises": [
      {"q": "Quina frase està ben puntuada?", "o": ["Els representants dels sindicats van manifestar la seua oposició a l'acord.", "Els representants dels sindicats, van manifestar la seua oposició a l'acord.", "Els representants dels sindicats van manifestar, la seua oposició a l'acord."], "e": "No s'escriu coma entre el subjecte i el verb ni entre el verb i el complement directe (GVB 15.3.3)."},
      {"q": "«La gran majoria dels veïns que havien assistit a l'assemblea de dijous ___ votaren a favor.» Cal una coma darrere de «dijous»?", "o": ["No: no es posa coma entre el subjecte i el verb, encara que el subjecte siga llarg", "Sí: quan el subjecte és llarg és obligatòria", "Sí, però només en textos administratius"], "e": "La llargària del subjecte no justifica una coma entre el subjecte i el verb (GVB 15.3.3.a)."},
      {"q": "Quina frase està ben puntuada?", "o": ["L'alcaldessa va lliurar als guanyadors del certamen les distincions corresponents.", "L'alcaldessa va lliurar als guanyadors del certamen, les distincions corresponents.", "L'alcaldessa va lliurar, als guanyadors del certamen les distincions corresponents."], "e": "No s'escriu coma entre el verb i els complements ni entre el complement indirecte i el directe (GVB 15.3.3.b)."},
      {"q": "Quina frase està ben puntuada?", "o": ["La conclusió més important de l'informe és que cal reduir la despesa.", "La conclusió més important de l'informe és, que cal reduir la despesa.", "La conclusió més important de l'informe, és que cal reduir la despesa."], "e": "No es posa coma entre el subjecte i el verb, ni entre el verb copulatiu i l'atribut, encara que siga una oració (GVB 15.3.3)."},
      {"q": "Quina frase està ben puntuada?", "o": ["El jurat va declarar deserta la segona edició del certamen.", "El jurat va declarar, deserta la segona edició del certamen.", "El jurat va declarar deserta, la segona edició del certamen."], "e": "Ni entre el verb i el complement predicatiu ni entre el predicatiu i el complement directe s'ha d'escriure coma (GVB 15.3.3.b)."},
      {"q": "Quina frase està ben puntuada?", "o": ["La directora ens va comunicar, amb una certa recança, que la reunió s'ajornava.", "La directora ens va comunicar, amb una certa recança que la reunió s'ajornava.", "La directora ens va comunicar amb una certa recança, que la reunió s'ajornava."], "e": "Entre el verb i el complement no hi pot haver una coma sola; si s'hi intercala un incís, s'ha de tancar entre dos comes (GNV 7.3.1.1.c; GVB 15.3.3.b)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Els llibres, les revistes, els mapes, etc., formen part del fons de la biblioteca.", "Els llibres, les revistes, els mapes, etc. formen part del fons de la biblioteca.", "Els llibres, les revistes, els mapes etc., formen part del fons de la biblioteca."], "e": "Quan el subjecte és una enumeració tancada amb etc., cal acotar-la entre comes; el punt de l'abreviatura pot anar seguit de coma (GVB 15.3.1.a; GNV 7.2.1)."},
      {"q": "Quina puntuació expressa que només no podran votar els socis que no han pagat?", "o": ["Els socis que no havien pagat la quota no podran votar.", "Els socis, que no havien pagat la quota, no podran votar.", "Els socis que no havien pagat la quota, no podran votar."], "e": "La relativa especificativa restringix l'antecedent i no porta comes; amb comes seria explicativa i afectaria tots els socis (GNV 7.3.1.1.c, obs.)."},
      {"q": "En «Els veïns, que estaven indignats, van tallar el carrer», què s'entén?", "o": ["Que tots els veïns estaven indignats i van tallar el carrer", "Que només van tallar el carrer els veïns que estaven indignats", "Que els veïns indignats no van tallar el carrer"], "e": "Les comes fan explicativa la relativa: la informació afecta tot l'antecedent (GNV 7.3.1.1.c, obs.)."},
      {"q": "Com s'anomena la relativa que va entre comes i afecta tot l'antecedent? Escriu «relativa ___».", "a": ["explicativa"], "e": "Les relatives explicatives se separen amb comes de l'oració principal (GNV 7.3.1.1.c, obs.)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Vicent Andrés Estellés, poeta de Burjassot, va escriure el Mural del País Valencià.", "Vicent Andrés Estellés poeta de Burjassot, va escriure el Mural del País Valencià.", "Vicent Andrés Estellés, poeta de Burjassot va escriure el Mural del País Valencià."], "e": "Un incís explicatiu s'aïlla amb dos comes, l'una d'obertura i l'altra de tancament (GNV 7.3.1.1.c)."},
      {"q": "Quina frase està ben puntuada?", "o": ["El poeta Estellés va nàixer a Burjassot.", "El poeta, Estellés, va nàixer a Burjassot.", "El poeta Estellés, va nàixer a Burjassot."], "e": "Una aposició especificativa no s'aïlla amb comes, i entre el subjecte i el verb no s'escriu coma (GNV 7.3.1.1.c; GVB 15.3.3.a)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Pensàvem que l'expedient estava tancat, i després vam saber que l'havien reobert.", "Pensàvem que l'expedient estava tancat i, després vam saber que l'havien reobert.", "Pensàvem, que l'expedient estava tancat i després vam saber que l'havien reobert."], "e": "Quan els membres coordinats són independents entre si, s'escriu coma encara que vagen units per la conjunció i (GNV 7.3.1.1.b, obs.)."},
      {"q": "En «Obri de dilluns a divendres, de 9 a 14 hores i de 15 a 19 hores, i dissabtes, de 9 a 13 hores», per què hi ha coma davant de «i dissabtes»?", "o": ["Perquè la conjunció unix elements que ja contenen termes coordinats", "Perquè sempre es posa coma davant de l'últim element", "És un error: mai no es posa coma davant de i"], "e": "Es posa coma davant de i quan unix elements que ja contenen termes coordinats o introduïx un contingut diferent (GVB 15.3.1.a)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Si l'informe arriba a temps, el debatrem en el ple de dijous.", "Si l'informe arriba a temps el debatrem, en el ple de dijous.", "Si, l'informe arriba a temps el debatrem en el ple de dijous."], "e": "La subordinada condicional o adverbial anteposada se separa amb coma de la principal (GNV 7.3.1.1.e)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Debatrem l'informe en el ple de dijous si arriba a temps.", "Debatrem l'informe en el ple de dijous si, arriba a temps.", "Debatrem l'informe, en el ple de dijous si arriba a temps."], "e": "Quan la temporal o la condicional va posposada a la principal, la coma no és necessària (GVB 15.3.1.e)."},
      {"q": "En quina d'estes frases és acceptable ometre la coma després de la subordinada anteposada?", "o": ["Si vols vine.", "Quan els tècnics municipals hagen revisat tota la documentació presentada pels veïns la comissió es reunirà.", "Encara que la proposta haja sigut aprovada per una àmplia majoria dels assistents no s'aplicarà fins a l'any vinent."], "e": "Esta coma es pot ometre segons la llargària i la complexitat de la frase, com en les oracions curtes: Si vols vine (GNV 7.3.1.1.e, obs.)."},
      {"q": "Quina frase està ben puntuada?", "o": ["No ho ha signat el tresorer, sinó la secretària.", "No ho ha signat el tresorer sinó, la secretària.", "No ho ha signat, el tresorer sinó la secretària."], "e": "Les oracions adversatives se separen amb coma (GNV 7.3.1.1.h)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Ja ha signat el contracte, de manera que no pot fer-se arrere.", "Ja ha signat el contracte de manera, que no pot fer-se arrere.", "Ja ha signat, el contracte de manera que no pot fer-se arrere."], "e": "Les oracions consecutives s'acoten amb coma (GVB 15.3.1.e)."},
      {"q": "Quina frase està ben puntuada?", "o": ["L'empresa ha tancat l'any amb pèrdues i, tanmateix, repartirà dividends.", "L'empresa ha tancat l'any amb pèrdues i tanmateix, repartirà dividends.", "L'empresa ha tancat l'any amb pèrdues, i tanmateix repartirà, dividends."], "e": "Els connectors com tanmateix, no obstant això o per tant s'aïllen entre comes (GNV 7.3.1.1.g)."},
      {"q": "Quina frase està ben puntuada?", "o": ["L'informe tècnic és desfavorable; no obstant això, si s'esmenen les deficiències, l'expedient es podrà revisar.", "L'informe tècnic és desfavorable, no obstant això si s'esmenen les deficiències, l'expedient es podrà revisar.", "L'informe tècnic és desfavorable; no obstant això; si s'esmenen les deficiències, l'expedient es podrà revisar."], "e": "Davant d'un connector adversatiu o concessiu que unix estructures amb comes internes s'usa punt i coma (GNV 7.3.2.b)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Hi van intervindre la degana, Sra. Ferrer; el vicedegà, Sr. Pla, i la secretària, Sra. Bou.", "Hi van intervindre la degana, Sra. Ferrer; el vicedegà, Sr. Pla; i la secretària, Sra. Bou.", "Hi van intervindre la degana, Sra. Ferrer, el vicedegà, Sr. Pla, i la secretària, Sra. Bou."], "e": "En una enumeració complexa amb comes internes els elements se separen amb punt i coma, però davant de i es posa coma (GNV 7.3.2.a i obs.)."},
      {"q": "Escriu el nom del signe que separa els elements d'una enumeració complexa que ja contenen comes.", "a": ["punt i coma", "el punt i coma"], "e": "En les enumeracions llargues o complexes amb comes internes, els grups se separen amb punt i coma (GNV 7.3.2.a)."},
      {"q": "Quin signe és més adequat? «Hui encara som a temps d'actuar ___ demà, probablement, serà massa tard.»", "o": ["Punt i coma", "Coma", "Cap signe"], "e": "El punt i coma separa frases completes estretament unides pel significat (GNV 7.3.2.c; GVB 15.4.c)."},
      {"q": "Escriu el nom del signe que falta: «L'informe és negatiu___ no obstant això, si s'esmenen les deficiències, es revisarà l'expedient.»", "a": ["punt i coma", "un punt i coma"], "e": "Davant d'un connector adversatiu que unix estructures amb comes internes s'usa punt i coma (GNV 7.3.2.b)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Els de primer, que ja havien acabat, se'n van anar a casa; els de segon, en canvi, es van quedar a la biblioteca.", "Els de primer, que ja havien acabat, se'n van anar a casa, els de segon, en canvi, es van quedar a la biblioteca.", "Els de primer que ja havien acabat; se'n van anar a casa, els de segon en canvi es van quedar a la biblioteca."], "e": "Quan les oracions ja contenen comes internes, el punt i coma marca la frontera principal (GNV 7.3.2.a i c)."},
      {"q": "Quina frase està ben puntuada?", "o": ["La primera part va durar dues hores; la segona, tres quarts.", "La primera part va durar dues hores, la segona tres quarts.", "La primera part va durar dues hores; la segona tres quarts."], "e": "La coma marca l'elisió del verb en una oració coordinada amb una de precedent: Ells votaren que sí; nosaltres, que no (GNV 7.3.1.1.f)."},
      {"q": "Escriu el nom del signe que indica el verb elidit: «Ells votaren que sí; nosaltres___ que no.»", "a": ["coma", "una coma"], "e": "La coma marca l'elisió del verb (GNV 7.3.1.1.f)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Eixe expedient, ja el vaig revisar ahir.", "Eixe expedient ja, el vaig revisar ahir.", "Eixe expedient ja el vaig revisar, ahir."], "e": "La coma pot indicar la inflexió tonal d'un element dislocat a l'esquerra i représ per un pronom (GNV 7.3.1.1.d)."},
      {"q": "Quina frase està ben puntuada?", "o": ["No en vull saber res, d'eixes històries.", "No en vull saber, res d'eixes històries.", "No, en vull saber res d'eixes històries."], "e": "L'element dislocat a la dreta se separa amb coma: No és pròpia de tu, esta actitud (GNV 7.3.1.1.d)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Conclòs el tràmit d'audiència, l'instructor trametrà l'expedient.", "Conclòs el tràmit d'audiència l'instructor, trametrà l'expedient.", "Conclòs, el tràmit d'audiència l'instructor trametrà l'expedient."], "e": "Les clàusules absolutes de participi o de gerundi se separen amb coma (GVB 15.3.1.h)."},
      {"q": "«Conclòs el tràmit d'audiència, l'instructor trametrà l'expedient.» Escriu de quin tipus és la clàusula absoluta inicial: «clàusula absoluta de ___».", "a": ["participi"], "e": "Les clàusules absolutes de participi o de gerundi se separen amb coma de la resta de l'oració (GVB 15.3.1.h)."},
      {"q": "Quina puntuació indica que és Joan qui ho farà si ve una altra persona?", "o": ["Si ve, Joan ho farà.", "Si ve Joan, ho farà.", "Si ve Joan ho farà."], "e": "La coma també servix per a evitar ambigüitats (GNV 7.3.1.1.j; GVB 15.3.1.i)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Et demane, senyora presidenta, que retire eixes paraules.", "Et demane senyora presidenta, que retire eixes paraules.", "Et demane, senyora presidenta que retire eixes paraules."], "e": "El vocatiu s'aïlla amb comes; si va enmig de la frase, entre dos comes (GNV 7.3.1.1.a)."},
      {"q": "Quin titular està ben puntuat?", "o": ["La reforma de l'horta, a debat", "La reforma, de l'horta a debat", "La reforma de l'horta a, debat"], "e": "La coma separa els constituents de les oracions nominals, com en titulars i refranys: Per l'agost, figues i most (GNV 7.3.1.1.i)."},
      {"q": "Quina frase està ben puntuada?", "o": ["L'alcalde —que, segons diuen, no en sabia res— va convocar una roda de premsa.", "L'alcalde —que segons diuen, no en sabia res— va convocar una roda de premsa.", "L'alcalde, que —segons diuen— no en sabia res, va convocar, una roda de premsa."], "e": "Un incís dins d'un altre incís es marca amb un signe diferent i cada un s'ha de tancar; a més, no s'escriu coma entre el verb i el complement directe (GNV 7.5.1.a i 7.3.1.1.c)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Quan va arribar la notícia —ningú no se l'esperava—, tots van callar.", "Quan va arribar la notícia —ningú no se l'esperava,— tots van callar.", "Quan va arribar la notícia, —ningú no se l'esperava— tots van callar."], "e": "El signe de tancament de l'incís es manté i s'escriu davant del signe de pausa quan l'incís comença dins de la frase (GNV 7.2.3)."},
      {"q": "Quina frase està ben puntuada?", "o": ["La vila s'alça al peu de la serra d'Espadà (1.030 m), prop del riu Anna.", "La vila s'alça al peu de la serra d'Espadà, (1.030 m) prop del riu Anna.", "La vila s'alça al peu de la serra d'Espadà (1.030 m,) prop del riu Anna."], "e": "Quan un parèntesi de tancament coincidix amb una coma, la coma va fora i immediatament darrere del parèntesi (GNV 7.5.2.a, obs.; 7.2.3)."},
      {"q": "Quina frase està ben puntuada?", "o": ["El termini acaba el 30 de juny. (Les sol·licituds fora de termini no s'admetran.)", "El termini acaba el 30 de juny. (Les sol·licituds fora de termini no s'admetran).", "El termini acaba el 30 de juny (les sol·licituds fora de termini no s'admetran.)"], "e": "Si el parèntesi inicia una frase, el punt va dins; si s'obri a l'interior d'una frase, el punt va fora (GNV 7.2.3; GVB 15.11.2)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Va declarar que «el projecte no té marxa enrere».", "Va declarar que «el projecte no té marxa enrere.»", "Va declarar que, «el projecte no té marxa enrere»."], "e": "Si les cometes s'obrin dins de la frase, el punt s'escriu darrere de les cometes de tancament; i entre el verb i el complement no hi va coma (GVB 15.13.2 i 15.3.3.b)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Vull saber tres coses: on?, quan? i amb qui?", "Vull saber tres coses: on?. quan? i amb qui?", "Vull saber tres coses: on? quan? i amb qui?."], "e": "Els signes d'interrogació poden anar seguits de coma, però mai de punt (GNV 7.2.2 i obs.)."},
      {"q": "Escriu el nom del signe que no pot anar mai immediatament darrere d'un signe d'interrogació o d'exclamació.", "a": ["punt", "el punt"], "e": "Els signes d'interrogació i d'exclamació poden anar seguits de coma, punt i coma o dos punts, però no de punt: Quan vindràs? (GNV 7.2.2, obs.; GVB 15.5.3.e)."},
      {"q": "Quina frase està ben puntuada?", "o": ["Hi havia representants de Belarús, Estònia i Lituània.", "Hi havia representants de: Belarús, Estònia i Lituània.", "Hi havia representants de Belarús, Estònia, i Lituània."], "e": "No s'escriuen dos punts entre una preposició i el substantiu que introduïx, ni coma davant de la i que tanca una enumeració simple (GVB 15.6.3; GNV 7.3.1.1.b, obs.)."},
      {"q": "Quina frase està ben puntuada?", "o": ["—Si estàs cansada, descansa —va suggerir l'Elvira—. Demà serà un altre dia.", "—Si estàs cansada, descansa— va suggerir l'Elvira. Demà serà un altre dia.", "—Si estàs cansada, descansa, va suggerir l'Elvira—. Demà serà un altre dia."], "e": "Quan les paraules del narrador interrompen la intervenció del personatge, s'acoten amb un guió d'obertura i un de tancament (GVB 15.10.c; GNV 7.5.1)."},
      {"q": "Escriu el nom del signe d'incís que emmarca les paraules del narrador en un diàleg.", "a": ["guió", "el guió", "guions", "els guions"], "e": "El guió marca l'inici del parlament i emmarca els comentaris del narrador (GNV 7.5.1.b; GVB 15.10)."},
      {"q": "Quin signe d'incís aïlla més fortament l'incís de la resta de l'oració?", "o": ["Els parèntesis", "Les comes", "Els guions"], "e": "En la gradació dels incisos, les comes els integren en l'oració, els guions els destaquen més i els parèntesis els aïllen com a informació complementària o secundària (GNV 7.3.1.1.c, 7.5.1.a i 7.5.2.a)."},
      {"q": "Escriu el nom del tipus de relativa que no porta comes: «Els socis que no havien pagat no podran votar.»", "a": ["especificativa", "relativa especificativa", "oració especificativa", "oració relativa especificativa"], "e": "Les relatives especificatives no porten comes; les explicatives, sí (GNV 7.3.1.1.c, obs.)."},
      {"q": "Quantes comes cal escriure en «Burjassot ciutat de l'Horta Nord és la pàtria d'Estellés»? Escriu el número.", "a": ["2", "dos", "dues"], "e": "Dues: una davant i una darrere de l'aposició explicativa «ciutat de l'Horta Nord» (GNV 7.3.1.1.c)."}
    ]
  }
]$data$::jsonb) AS t(
  id uuid, type text, sort_order smallint, title text, name text,
  content text, icon text, color text, exercises jsonb
);

INSERT INTO public.resources (id, name, type, category, content, difficulty, xp_earned, sort_order, metadata)
SELECT id, name, type, 'fonetica_ortografia', content, 'C2', 15, sort_order,
       jsonb_build_object('icon', icon, 'color', color, 'section_name', title)
FROM practice_catalog
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  type = EXCLUDED.type,
  category = EXCLUDED.category,
  content = EXCLUDED.content,
  difficulty = EXCLUDED.difficulty,
  xp_earned = EXCLUDED.xp_earned,
  sort_order = EXCLUDED.sort_order,
  -- Conserva la lliçó fixa («Aprendre lliçó»), si una migració posterior n'hi afig.
  metadata = EXCLUDED.metadata || jsonb_strip_nulls(jsonb_build_object('lesson', resources.metadata -> 'lesson'));

DELETE FROM public.practice_exercises e
USING practice_catalog c
WHERE e.resource_id = c.id AND e.level = 'C2';

INSERT INTO public.practice_exercises (resource_id, level, position, kind, prompt, options, answers, explanation)
SELECT c.id, 'C2', x.ord,
       CASE WHEN x.e ? 'a' THEN 'fill' ELSE 'choice' END,
       x.e->>'q',
       CASE WHEN x.e ? 'o' THEN ARRAY(SELECT jsonb_array_elements_text(x.e->'o')) END,
       CASE WHEN x.e ? 'a' THEN ARRAY(SELECT jsonb_array_elements_text(x.e->'a')) ELSE ARRAY[x.e->'o'->>0] END,
       x.e->>'e'
FROM practice_catalog c
CROSS JOIN LATERAL jsonb_array_elements(c.exercises) WITH ORDINALITY AS x(e, ord);

DROP TABLE practice_catalog;
